from rcb_kinder import Session
import numpy as np
s=Session();s.reset();e=s.env.unwrapped._object_centric_env;A=[]
def ee():return np.array(e.robot.arm.get_end_effector_pose().position)
def act(dx=0,dy=0,d2=0,d4=0,grip=0):
 a=np.zeros(11);a[[0,1,4,6,10]]=[dx,dy,d2,d4,grip];old=ee();o,success,done=s.step(a);A.append(a)
 p=ee();print(s.t,'a',np.round(a[[0,1,4,6,10]],3),'ee',np.round(p,3),'moved',np.round(p-old,3),'grasp',s.state().grasped_object,flush=True)
 s.save_trajectory(A,'/app/output/trajectory.npz');return success
for _ in range(3):act(dy=.095)
for _ in range(10):act(d2=.075,d4=.045)
act(grip=-1)
for _ in range(3):act(d2=-.08)
for dy in [-.1,-.1,-.1,-.07393]:act(dy=dy)
act(dx=-.01265)
for _ in range(2):act(d2=.08)
act(d2=.07)
act(grip=1)
print(s.state().pretty_str())
print('seated',e._part_is_seated_in_rack('part0',s.state()),'goal',e.goal_reached())

# part1 pickup
for _ in range(3):act(d2=-.08)
for dy in [-.1,-.1,-.0096]:act(dy=dy)
act(dx=-.03265)
for _ in range(3):act(d2=.08)
act(grip=-1)
print('part1 grasp',s.state().grasped_object, 'ee',ee(),flush=True)

# part1 placement
for _ in range(3):act(d2=-.08)
for dy in [.1,.1,.1,.026176]:act(dy=dy)
act(dx=-.023567)
for _ in range(2):act(d2=.08)
act(d2=.07)
act(grip=1)
print('part1 seated',e._part_is_seated_in_rack('part1',s.state()),'part pose',s.state().get_object_pose('part1'),flush=True)

# part2 pickup
for _ in range(3):act(d2=-.08)
for dy in [.1,.1,.1,.04139]:act(dy=dy)
act(dx=.01367)
for _ in range(3):act(d2=.08)
act(d2=.01)
act(grip=-1)
print('part2 grasp',s.state().grasped_object,'ee',ee(),flush=True)

# part2 placement
for _ in range(3):act(d2=-.08)
for dy in [-.1,-.1,-.1,-.010047]:act(dy=dy)
act(dx=.046264)
for _ in range(2):act(d2=.08)
act(d2=.07)
act(grip=1)
print('part2 seated',e._part_is_seated_in_rack('part2',s.state()),'part pose',s.state().get_object_pose('part2'),flush=True)
print('goal',e.goal_reached(),'steps',len(A),flush=True)
print('replay',s.replay(A),flush=True)
